Can you review this class for SOLID violations?

```ts
type Currency = "USD" | "EUR";
interface Order { region: string; amount: number; currency: Currency; fxRateToUsd: number; status: "paid" | "refunded" }
interface ReportRow { region: string; total: number }

interface OrderRepo {
  findByMonth(month: string): Promise<Order[]>;
}

export class RevenueReport {
  constructor(private readonly orders: OrderRepo) {}

  async build(month: string): Promise<ReportRow[]> {
    const orders = await this.orders.findByMonth(month);
    const byRegion = new Map<string, number>();
    for (const o of orders) {
      if (o.status === "refunded") continue;
      byRegion.set(o.region, (byRegion.get(o.region) ?? 0) + this.toUsd(o));
    }
    return [...byRegion].map(([region, total]) => ({ region, total }));
  }

  toCsv(rows: ReportRow[]): string {
    return ["region,total", ...rows.map((r) => `${r.region},${r.total.toFixed(2)}`)].join("\n");
  }

  async sendToFinance(month: string): Promise<void> {
    const csv = this.toCsv(await this.build(month));
    const smtp = new SmtpClient(process.env.SMTP_HOST!, 587);
    await smtp.send({
      to: "finance@example.com",
      subject: `Revenue ${month}`,
      attachments: [{ filename: `revenue-${month}.csv`, content: csv }],
    });
  }

  private toUsd(o: Order): number {
    switch (o.currency) {
      case "USD":
        return o.amount;
      case "EUR":
        return o.amount * o.fxRateToUsd;
    }
  }
}
