func LateFee(daysLate int, m MemberType) int {
	if daysLate <= 0 {
		return 0
	}
	perDay := 25
	if m == Student {
		perDay = 10
	}
	fee := daysLate * perDay
	if fee > 1000 {
		fee = 1000
	}
	return fee
}
