type Processor interface {
	Process(ctx context.Context, job Job) error
}

func RunAll(ctx context.Context, p Processor, jobs []Job) error {
	for _, j := range jobs {
		if err := p.Process(ctx, j); err != nil {
			return fmt.Errorf("job %s: %w", j.ID, err)
		}
	}
	return nil
}

type Cache[K comparable, V any] struct {
	mu sync.Mutex
	m  map[K]V
}

func (c *Cache[K, V]) Get(k K) (V, bool) { c.mu.Lock(); defer c.mu.Unlock(); v, ok := c.m[k]; return v, ok }
func (c *Cache[K, V]) Put(k K, v V)      { c.mu.Lock(); defer c.mu.Unlock(); c.m[k] = v }

// Store holds JSON blobs; callers unmarshal what they get back.
type Store interface {
	Get(ctx context.Context, key string) ([]byte, error)
	Put(ctx context.Context, key string, val []byte) error
}

